<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Repositories\BudgetRepository;use App\Repositories\CategoryRepository;
final class BudgetController { public function index(Request $r):void{PermissionMiddleware::require('budgets.view');$rows=(new BudgetRepository())->allVisible(auth_user());$categories=(new CategoryRepository())->allForUser((int)Session::get('user_id'),true);View::render('budgets/index',compact('rows','categories'));} public function store(Request $r):void{PermissionMiddleware::require('budgets.create');verify_csrf();$d=$r->all();if((float)($d['budget_amount']??0)<=0)throw new \InvalidArgumentException('Budget amount must be greater than zero.');(new BudgetRepository())->create($d,(int)Session::get('user_id'));Session::flash('success','Budget created.');Response::redirect('/budgets');} public function delete(Request $r,string $id):void{PermissionMiddleware::require('budgets.delete');verify_csrf();(new BudgetRepository())->delete((int)$id,(int)Session::get('user_id'));Session::flash('success','Budget deleted.');Response::redirect('/budgets');}}
